with.command:
set -eu
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
printf '{"login":"%s"}' "$forge_as"

set -eu
cd "$REPO"
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
seen=$(forge pr list --head "$BRANCH" --state merged --json number,headRefOid,mergeCommit,closingIssuesReferences --jq '.[0] | select(. != null) | [.number, .headRefOid, .mergeCommit.oid, ([.closingIssuesReferences[].number | tostring] | join(","))] | @tsv')
[ -n "$seen" ] || { echo "no merged pull request carries $BRANCH: there is no proof to close with" >&2; exit 1; }
number=$(printf '%s' "$seen" | cut -f1); head=$(printf '%s' "$seen" | cut -f2); commit=$(printf '%s' "$seen" | cut -f3)
closes=$(printf '%s' "$seen" | cut -f4)
if [ -n "$ISSUE" ]; then
    case ",$closes," in *",$ISSUE,"*) ;; *) echo "pull request #$number closes ${closes:-none}, not #$ISSUE: the work never named it" >&2; exit 1 ;; esac
fi
[ -n "$commit" ] && [ "$commit" != null ] || commit=$head
git fetch -q --no-tags "$REMOTE_NAME"
trunk=$(git rev-parse "refs/remotes/$REMOTE_NAME/$BASE")
git merge-base --is-ancestor "$commit" "$trunk" || { echo "the remote $BASE does not carry $commit" >&2; exit 1; }
squashed=false
if ! git merge-base --is-ancestor "$head" "$trunk"; then
    # A squash leaves the head off the trunk: it is proved by content, the head merged onto
    # the squash's parent must give exactly the squash's tree.
    parent=$(git rev-parse --verify "$commit^") || { echo "the merge commit $commit has no parent to compare against" >&2; exit 1; }
    replayed=$(git merge-tree --write-tree "$parent" "$head") || { echo "$head does not merge cleanly onto $parent: not the content of $commit" >&2; exit 1; }
    squash_tree=$(git rev-parse --verify "$commit^{tree}") || { echo "cannot read the tree of $commit" >&2; exit 2; }
    [ "$replayed" = "$squash_tree" ] || { echo "the remote $BASE carries neither $head nor its content in $commit" >&2; exit 1; }
    squashed=true
fi
printf '{"number":%s,"head":"%s","commit":"%s","trunk":"%s","squashed":%s}' "$number" "$head" "$commit" "$trunk" "$squashed"

set -eu
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "$TRUNK:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
set +e
"$REPO/scripts/privacy-scan.sh" --text "$TEXT_FILE" >&2
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan --text exited $code on $TEXT_FILE; the text does not leave" >&2; exit "$code"; }
sha=$(shasum -a 256 < "$TEXT_FILE" | awk '{ print $1 }')
printf '{"text_file":"%s","sha256":"%s","privacy_exit":0}' "$TEXT_FILE" "$sha"

set -eu
cd "$REPO"
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
text_now=$(shasum -a 256 < "$TEXT_FILE") || { echo "cannot read $TEXT_FILE to compare it with what the gate judged" >&2; exit 2; }
[ "${text_now%% *}" = "$TEXT_SHA" ] || { echo "$TEXT_FILE changed after the publication gate judged it: nothing leaves" >&2; exit 1; }
state=$(forge issue view "$ISSUE" --json state --jq .state)
if [ "$state" != CLOSED ]; then
    forge issue close "$ISSUE" --comment "$(cat "$TEXT_FILE")" >&2
    state=$(forge issue view "$ISSUE" --json state --jq .state)
fi
[ "$state" = CLOSED ] || { echo "issue $ISSUE reads $state after closing" >&2; exit 1; }
printf '{"issue":"%s","state":"%s"}' "$ISSUE" "$state"

set -eu
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote "$REMOTE_NAME" "$1") || { code=$?; echo "cannot read $1 on $REMOTE_NAME: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
git -C "$REPO" fetch -q --no-tags "$REMOTE_NAME"
tip=$(read_remote_ref "refs/heads/$BRANCH")
if [ -n "$tip" ]; then
    git -C "$REPO" cat-file -e "$tip^{commit}" 2>/dev/null || git -C "$REPO" fetch -q --no-tags "$REMOTE_NAME" "$tip"
    [ "$tip" = "$HEAD_PROVED" ] || git -C "$REPO" merge-base --is-ancestor "$tip" "$TRUNK_COMMIT" || { echo "the remote $BRANCH at $tip carries commits the remote $BASE does not" >&2; exit 1; }
fi
printf '{"tip":"%s"}' "$tip"

set -eu
# The policy is the file the trunk commits, read with git: a sailor on PATH never decides who authorizes.
trusted_policy() {
    policy_commit=$(git -C "$REPO" rev-parse --verify --quiet "$TRUNK^{commit}") || { echo "the trunk $TRUNK does not exist in this tree: no trusted policy to read" >&2; exit 1; }
    policy_text=$(git -C "$REPO" show "$policy_commit:.sailor/delivery-policy.json") || { echo "$TRUNK at $policy_commit carries no .sailor/delivery-policy.json" >&2; exit 1; }
    printf '%s' "$policy_text" | POLICY_COMMIT="$policy_commit" python3 -c '
import json, os, sys
def no_constant(name):
    raise ValueError("%s is not JSON" % name)
try:
    policy = json.loads(sys.stdin.read(), parse_constant=no_constant)
except ValueError as error:
    sys.exit("the delivery policy is not JSON: %s" % error)
if not isinstance(policy, dict):
    sys.exit("the delivery policy is not an object")
lines = []
for field in ("merge", "push", "release"):
    if policy.get(field) not in ("auto", "ask"):
        sys.exit("the delivery policy does not say auto or ask for %s" % field)
    lines.append("%s: %s" % (field, policy[field]))
lines.append(os.environ["POLICY_COMMIT"])
print("\n".join(lines))
'
}
policy_now=$(trusted_policy) || exit 1
policy_was=$(printf '%s' "$POLICY_READ" | python3 -c 'import json,sys; p=json.load(sys.stdin); print("merge: %s\npush: %s\nrelease: %s\n%s" % (p["merge"], p["push"], p["release"], p["read_from"]))')
[ "$policy_now" = "$policy_was" ] || { echo "the delivery policy changed since it was read: the authorization in flight no longer holds; run the flow again" >&2; exit 1; }
url=$(git -C "$REPO" remote get-url "$REMOTE_NAME") || { echo "the tree has no remote named $REMOTE_NAME" >&2; exit 1; }
set -- -C "$REPO"
case "$url" in
    /*|file://*) ;;
    http://*|https://*)
        push_as=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        [ -n "$push_as" ] || { echo "sailor.pushAs is empty on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        helper='!f() { printf "%s\\n" username=x-access-token; printf "password=%s\\n" "$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "'"$push_as"'")"; }; f'
        set -- -C "$REPO" -c credential.helper= -c "credential.helper=$helper" ;;
    *) echo "$REMOTE_NAME is $url: a push over it cannot be bound to sailor.pushAs, so this flow refuses it" >&2; exit 1 ;;
esac
if [ -n "$TIP" ]; then
    git "$@" push --force-with-lease="refs/heads/$BRANCH:$TIP" "$REMOTE_NAME" ":refs/heads/$BRANCH" >&2
fi
printf '{"deleted":"%s"}' "$TIP"

set -eu
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote "$REMOTE_NAME" "$1") || { code=$?; echo "cannot read $1 on $REMOTE_NAME: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
cd "$REPO"
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
if [ -n "$ISSUE" ]; then
    state=$(forge issue view "$ISSUE" --json state --jq .state)
    [ "$state" = CLOSED ] || { echo "issue $ISSUE reads $state" >&2; exit 1; }
else
    state=none
fi
! git worktree list --porcelain | grep -F -x -q "branch refs/heads/$BRANCH" || { echo "a worktree still holds $BRANCH" >&2; exit 1; }
! git rev-parse --verify --quiet "refs/heads/$BRANCH" >/dev/null || { echo "the local $BRANCH still exists" >&2; exit 1; }
remote_left=$(read_remote_ref "refs/heads/$BRANCH")
[ -z "$remote_left" ] || { echo "the remote $BRANCH still exists at $remote_left" >&2; exit 1; }
archived=$(read_remote_ref "refs/tags/archive/$BRANCH")
[ -n "$archived" ] || { echo "the remote carries no refs/tags/archive/$BRANCH: the deleted branch has no archive" >&2; exit 1; }
printf '{"issue_state":"%s","commit":"%s","archived":"%s"}' "$state" "$COMMIT" "$archived"
